        for(int j=1;j<=n;j++) printf("%d ",a[i][j]);
        puts("");
    }
    puts("");
    for(int i=1;i<=n;i++){
        for(int j=1;j<=n;j++) printf("%d ",b[i][j]);
        puts("");
    }
    puts("");
        for(int i=1;i<=n;i++){
        for(int j=1;j<=n;j++) printf("%d ",f[i][j]);
        puts("");
    }
    puts("");
    printf("%d %d -> ",m,o);
    //*/
    printf("%d\n",match.gao(m,e));
}

